};

function normalizeRecoveryMethod(raw) {
    const t = normalizeToken(raw);
    if (!t || t === 'rest' || t === 'short' || t === 'short rest' || t === 'break' || t === 'nap') return 'rest';
    if (t === 'meal' || t === 'food' || t === 'eat' || t === 'eating' || t === 'drink') return 'meal';
    if (t === 'sleep' || t === 'long' || t === 'long rest' || t === 'overnight') return 'sleep';
    if (t === 'healing' || t === 'heal' || t === 'potion' || t === 'elixir' || t === 'medicine' || t === 'magic') return 'healing';
    if (t === 'full' || t === 'max' || t === 'complete') return 'full';
    return '';
}

function clamp(value, min, max) {
    const num = Number(value);
    if (!Number.isFinite(num)) return min;
    return Math.min(max, Math.max(min, Math.round(num)));
}

function normalizeToken(value) {
    return String(value ?? '')
        .trim()
        .toLowerCase()
        .replace(/[_-]+/g, ' ')
        .replace(/\s+/g, ' ');
}

function normalizeProtection(raw) {
    const t = normalizeToken(raw);
    if (!t || t === 'none' || t === 'off' || t === 'unprotected') return 'none';
    if (t === 'condom' || t === 'condoms') return 'condom';
    if (t === 'dental barrier' || t === 'dental' || t === 'barrier' || t === 'dentalbarriers' || t === 'dental barriers') {
        return 'dental barrier';
    }
    if (t === 'charm' || t === 'anti drain charm' || t === 'antidrain charm' || t === 'anti-drain charm') {
        return 'charm';
    }
    if (t === 'ward' || t === 'wards') return 'ward';
    return VALID_PROTECTIONS.includes(t) ? t : '';
}

function normalizeContactType(raw) {
    const t = normalizeToken(raw);
    if (!t) return '';
    if (t === 'lips' || t === 'lip' || t === 'kiss' || t === 'kissing') return 'kiss';
    if (t === 'oral' || t === 'mouth') return 'oral';
    if (t === 'vaginal' || t === 'vagina' || t === 'pussy' || t === 'intercourse') return 'vaginal';
    if (t === 'anal' || t === 'anus') return 'anal';
    if (t === 'tail' || t === 'tail orifice') return 'tail';
    if (t === 'prolonged' || t === 'deep' || t === 'extended') return 'prolonged';
    return CONTACT_BASE_DRAIN[t] ? t : '';
}

function normalizeFeedSource(raw) {
    const t = normalizeToken(raw);
    if (!t) return '';
    if (t === 'vital' || t === 'energy' || t === 'vital energy' || t === 'vitality') return 'vitality';
    if (t === 'bread' || t === 'meal' || t === 'normal food' || t === 'ordinary food' || t === 'food') return 'food';
    if (t === 'dreams' || t === 'dream') return 'dream';
    if (t === 'ambient magic' || t === 'mana' || t === 'magic') return 'magic';
    if (t === 'devotion' || t === 'affection') return 'affection';
    if (t === 'praise') return 'praise';
    if (t === 'admiration' || t === 'attention') return 'admiration';
    return '';
}

function normalizeTrainStat(raw) {
    const t = normalizeToken(raw);
    if (!t) return '';
    if (t === 'dom' || t === 'dominance') return 'dominance';
    if (t === 'sub' || t === 'submission') return 'submission';
    if (t === 'disc' || t === 'discipline') return 'discipline';
    if (t === 'ctrl' || t === 'control') return 'control';
    if (t === 'domest' || t === 'domesticity' || t === 'domestic') return 'domesticity';
    if (t === 'pred' || t === 'predation' || t === 'hunt') return 'predation';
    if (t === 'conf' || t === 'confidence') return 'confidence';
    if (t === 'emp' || t === 'empathy') return 'empathy';
    if (t === 'pride') return 'pride';
    if (t === 'restraint') return 'restraint';
    return '';
}

function syncVitalityAndNeed(s) {
    s.succubusVitality = clamp(s.succubusVitality, 0, 100);
    s.sustenanceNeed = clamp(100 - s.succubusVitality, 0, 100);
    s.userVitality = clamp(s.userVitality, 0, 100);
    return s;
}

function initState() {
    return {
        name: 'Unknown',
        stage: 'Awakened',
        route: 'Undefined',
        routeLocked: false,
        bond: 0,
        trust: 5,
        succubusVitality: 50,
        sustenanceNeed: 50,
        discipline: 0,
        control: 0,
        dom: 10,
        sub: 10,
        tempt: 35,
        pride: 5,
        empathy: 15,
        domesticity: 0,
        predation: 10,
        confidence: 5,
        userVitality: 100,
        lastDrain: 0,
        protection: 'none',
        day: 0,
        neglectDays: 0,
        lowStatDays: 0,
        lowVitalityDays: 0,
        caredToday: false,
        rules: [],
        mood: 'Lost',
        need: 'Shelter',
        shownImages: [],
    };
}

function ensureStateShape(raw) {
    const base = initState();
    const s = raw && typeof raw === 'object' ? { ...base, ...raw } : base;
    s.name = String(s.name || 'Unknown').trim() || 'Unknown';
    s.stage = STAGE_ORDER[s.stage] !== undefined ? s.stage : 'Awakened';
    s.route = String(s.route || 'Undefined').trim() || 'Undefined';
    s.routeLocked = Boolean(s.routeLocked);
    for (const k of EVOLUTION_STAT_KEYS) {
        s[k] = clamp(s[k], 0, 100);
    }
    s.succubusVitality = clamp(s.succubusVitality, 0, 100);
    s.sustenanceNeed = clamp(100 - s.succubusVitality, 0, 100);
    s.userVitality = clamp(s.userVitality, 0, 100);
    s.lastDrain = clamp(s.lastDrain, 0, 100);
    s.protection = normalizeProtection(s.protection) || 'none';
    s.day = Math.max(0, Math.round(Number(s.day) || 0));
    s.neglectDays = Math.max(0, Math.round(Number(s.neglectDays) || 0));
    s.lowStatDays = Math.max(0, Math.round(Number(s.lowStatDays) || 0));
    s.lowVitalityDays = Math.max(0, Math.round(Number(s.lowVitalityDays) || 0));
    s.caredToday = Boolean(s.caredToday);
    s.rules = Array.isArray(s.rules) ? s.rules.map(r => String(r || '').trim()).filter(Boolean) : [];
    s.mood = String(s.mood || 'Lost').trim() || 'Lost';
    s.need = String(s.need || 'Shelter').trim() || 'Shelter';
    s.shownImages = Array.isArray(s.shownImages) ? s.shownImages.map(u => String(u || '').trim()).filter(Boolean) : [];
    return s;
}

function computeRouteScores(s) {
    const need = clamp(100 - s.succubusVitality, 0, 100);
    const horrorBonus =
        (s.neglectDays >= 3 ? (s.neglectDays - 2) * 30 : 0) +
        (s.lowStatDays >= 3 ? 45 : 0) +
        (s.lowVitalityDays >= 3 ? 45 : 0) +
        (need >= 70 && s.trust <= 20 && s.control <= 20 ? 55 : 0) +
        (need >= 85 && s.discipline <= 15 ? 45 : 0);

    const balanceSpread =
        Math.abs(s.control - s.discipline) +
        Math.abs(s.empathy - s.confidence);
    const balanceBonus =
        (s.control >= 30 && s.discipline >= 30 && s.empathy >= 25 && s.succubusVitality >= 55)
            ? Math.max(0, 45 - Math.floor(balanceSpread * 0.5))
            : 0;

    return {
        'Perfect Housewife': s.domesticity * 2.2 + s.bond * 1.1 + s.trust * 0.9 + s.discipline * 0.8 + s.sub * 0.4,
        'Loyal Demon Wife': s.bond * 1.3 + s.pride * 1.2 + s.confidence * 1.1 + s.discipline * 0.9 + s.dom * 0.3,
        'Huntress Succubus': s.predation * 2.1 + s.discipline * 1.0 + s.control * 0.6 + s.confidence * 0.4,
        'Guardian Succubus': s.bond * 0.9 + s.empathy * 1.0 + s.predation * 1.1 + s.discipline * 1.1 + s.control * 0.9,
        'Assertive Demoness': s.pride * 1.5 + s.confidence * 1.3 + s.tempt * 0.8 + s.dom * 1.0,
        'Court Succubus': s.pride * 1.2 + s.tempt * 1.1 + s.control * 1.1 + s.discipline * 1.0,
        'Gentle Companion': s.empathy * 1.8 + s.trust * 1.4 + s.bond * 1.0 - s.predation * 0.3,
        'Chaotic Temptress': s.tempt * 1.6 + Math.max(0, 35 - s.discipline) * 1.1 + Math.max(0, 25 - s.control) * 0.6,
        'Balanced Succubus': s.control * 1.2 + s.discipline * 1.1 + s.confidence * 0.9 + s.empathy * 0.9 + balanceBonus,
        'Starved Horror': need * 0.8 + horrorBonus - s.trust * 0.4 - s.control * 0.4 - s.discipline * 0.3,
    };
}

function isHorrorCondition(s) {
    const allLowForThreeDays = s.lowStatDays >= 3;
    const lowVitalityForThreeDays = s.lowVitalityDays >= 3;
    const highNeglectHungry = s.neglectDays >= 3 && s.succubusVitality < 75;
    return allLowForThreeDays || lowVitalityForThreeDays || highNeglectHungry || s.neglectDays >= 7;
}

function resolveBestRoute(s) {
    if (isHorrorCondition(s)) {
        return 'Starved Horror';
    }
    const scores = computeRouteScores(s);
    const order = [
        'Perfect Housewife',
        'Loyal Demon Wife',
        'Huntress Succubus',
        'Guardian Succubus',
        'Assertive Demoness',
        'Court Succubus',
        'Gentle Companion',
        'Chaotic Temptress',
        'Balanced Succubus',
        'Starved Horror',
    ];
    let bestRoute = 'Gentle Companion';
    let bestScore = -Infinity;
    for (const r of order) {
        if (scores[r] > bestScore) {
            bestScore = scores[r];
            bestRoute = r;
        }
    }
    return bestRoute;
}

function getHighestEvolutionStat(s) {
    let maxVal = 0;
    for (const key of EVOLUTION_STAT_KEYS) {
        if (s[key] > maxVal) maxVal = s[key];
    }
    return maxVal;
}

function getImageForState(stage, route) {
    if (stage === 'Awakened' || !route || route === 'Undefined') {
        return BASE_AWAKENED_IMAGE;
    }
    return IMAGE_DB[route + '|' + stage] || IMAGE_DB[stage] || BASE_AWAKENED_IMAGE;
}

function formatDisplayedRoute(s) {
    if (s.stage === 'Awakened' || !s.route || s.route === 'Undefined') {
        return 'Undefined';
    }
    if (s.stage === 'Imprinted' || s.stage === 'Shaped') {
        return s.route + ' Lean';
    }
    return s.route;
}

function evaluateProgression(s) {
    const prevStage = s.stage;
    const prevIdx = STAGE_ORDER[prevStage] ?? 0;
    let targetIdx = prevIdx;

    const maxStat = getHighestEvolutionStat(s);
    const horrorShaped = s.lowStatDays >= 3 || s.lowVitalityDays >= 3 || (s.neglectDays >= 3 && s.succubusVitality < 75);
    const horrorDefined = s.neglectDays >= 7;

    if (s.succubusVitality >= 100 && targetIdx < STAGE_ORDER.Imprinted) {
        targetIdx = STAGE_ORDER.Imprinted;
    }
    if ((maxStat >= 50 || horrorShaped) && targetIdx < STAGE_ORDER.Shaped) {
        targetIdx = STAGE_ORDER.Shaped;
    }
    if ((maxStat >= 75 || horrorDefined) && targetIdx < STAGE_ORDER.Defined) {
        targetIdx = STAGE_ORDER.Defined;
    }
    if (maxStat >= 100 && targetIdx < STAGE_ORDER.Ascendant) {
        targetIdx = STAGE_ORDER.Ascendant;
    }

    // Strict monotone stage progression: never regress.
    const nextIdx = Math.max(prevIdx, targetIdx);
    const nextStage = STAGES[nextIdx];
    s.stage = nextStage;

    if (nextIdx === STAGE_ORDER.Awakened) {
        s.route = 'Undefined';
        s.routeLocked = false;
    } else if (!s.routeLocked) {
        s.route = resolveBestRoute(s);
        if (nextIdx >= STAGE_ORDER.Defined) {
            s.routeLocked = true;
        }
    }

    if (nextIdx >= STAGE_ORDER.Defined) {
        s.routeLocked = true;
    }

    const stageChanged = nextIdx > prevIdx;
    const portraitUrl = getImageForState(s.stage, s.route);
    let appendMarkdown = '';
    if (stageChanged && portraitUrl && !s.shownImages.includes(portraitUrl)) {
        s.shownImages = [...s.shownImages, portraitUrl];
        appendMarkdown = '![](' + portraitUrl + ')';
    }

    return {
        stageChanged,
        prevStage,
        nextStage: s.stage,
        portraitUrl,
        appendMarkdown,
    };
}

function updateMoodAndNeed(s, overrideMood, overrideNeed) {
    if (overrideMood) {
        s.mood = overrideMood;
    } else if (s.route === 'Starved Horror' || s.sustenanceNeed >= 80) {
        s.mood = 'Starved';
    } else if (s.sustenanceNeed >= 60) {
        s.mood = 'Restless-hungry';
    } else if (s.stage === 'Awakened') {
        s.mood = s.trust >= 15 ? 'Wary-soft' : 'Lost';
    } else if (s.stage === 'Imprinted') {
        s.mood = s.trust >= 25 ? 'Attached' : 'Clingy-soft';
    } else if (s.stage === 'Shaped') {
        s.mood = s.route === 'Chaotic Temptress' ? 'Guilty-playful' : (s.route === 'Assertive Demoness' ? 'Testing' : 'Focused');
    } else if (s.stage === 'Defined') {
        s.mood = s.route === 'Perfect Housewife' ? 'Devoted' : (s.route === 'Guardian Succubus' ? 'Protective' : 'Centered');
    } else {
        s.mood = 'Self-possessed';
    }

    if (overrideNeed) {
        s.need = overrideNeed;
    } else if (s.route === 'Starved Horror' || s.sustenanceNeed >= 75) {
        s.need = 'Safe Feeding';
    } else if (s.userVitality <= 50) {
        s.need = 'Pace contact & protect partner';
    } else if (s.stage === 'Awakened' && s.name === 'Unknown') {
        s.need = 'Shelter & Name';
    } else if (s.rules.length === 0) {
        s.need = 'Clear household rules';
    } else if (s.stage === 'Imprinted') {
        s.need = 'Guidance';
    } else if (s.stage === 'Shaped') {
        s.need = 'Consistent training';
    } else if (s.stage === 'Defined') {
        s.need = 'Route mastery';
    } else {
        s.need = 'Chosen pact';
    }
}

function computeIntimacyProfile(s) {
    const domVsSub = s.dom - s.sub;
    const stance = domVsSub >= 12
        ? 'Dominant-leaning'
        : (domVsSub <= -12 ? 'Submissive-leaning' : 'Switch / Responsive');
    const safety = s.trust >= 50 && s.control >= 40
        ? 'Negotiated & attentive'
        : (s.discipline < 20 || s.sustenanceNeed >= 70 ? 'Hunger-pressured; requires pacing & protection' : 'Tentative & reactive');
    const themes = [];
    if (s.domesticity >= 20 || s.route === 'Perfect Housewife' || s.route === 'Loyal Demon Wife') {
        themes.push('praise & domestic devotion');
    }
    if (s.predation >= 25 || s.route === 'Huntress Succubus') {
        themes.push('claiming & chase');
    }
    if (s.pride >= 25 || s.route === 'Assertive Demoness' || s.route === 'Court Succubus') {
        themes.push('status play & teasing');
    }
    if (s.empathy >= 25 || s.route === 'Gentle Companion') {
        themes.push('emotional safety & softness');
    }
    if (themes.length === 0) {
        themes.push('comfort-seeking & curiosity');
    }
    return { stance, safety, themes };
}

function buildCompactHudText(s) {
    const displayedRoute = formatDisplayedRoute(s);
    return [
        '♡ My Succubus Companion',
        'Name: ' + s.name + ' | Stage: ' + s.stage + ' | Route: ' + displayedRoute,
        'Bond ' + s.bond + ' · Trust ' + s.trust + ' · Succubus Vitality ' + s.succubusVitality + ' · Sustenance Need ' + s.sustenanceNeed + ' · Discipline ' + s.discipline + ' · Control ' + s.control,
        'Dom ' + s.dom + ' · Sub ' + s.sub + ' · Tempt ' + s.tempt + ' · Pride ' + s.pride + ' · Empathy ' + s.empathy,
        '{{user}} Vitality ' + s.userVitality + '/100 · Last Drain ' + s.lastDrain + ' · Protection ' + s.protection + ' · Day ' + s.day + ' · Neglect ' + s.neglectDays,
        'Mood: ' + s.mood + ' | Need: ' + s.need,
    ].join('\n');
}

function applyDayRollover(s, count, forceNeglect) {
    const days = Math.max(1, clamp(count || 1, 1, 30));
    for (let i = 0; i < days; i++) {
        s.day += 1;
        const neglected = Boolean(forceNeglect) || !s.caredToday;
        if (neglected) {
            s.neglectDays += 1;
            s.succubusVitality = clamp(s.succubusVitality - 8, 0, 100);
            s.bond = clamp(s.bond - 2, 0, 100);
            s.trust = clamp(s.trust - 3, 0, 100);
            s.discipline = clamp(s.discipline - 1, 0, 100);
            s.control = clamp(s.control - 1, 0, 100);
            s.empathy = clamp(s.empathy - 2, 0, 100);
        } else {
            s.neglectDays = Math.max(0, s.neglectDays - 1);
            s.succubusVitality = clamp(s.succubusVitality - 4, 0, 100);
        }

        const allBelow15 = CORE_EVOLUTION_HUD_KEYS.every(k => s[k] < 15);
        if (allBelow15) {
            s.lowStatDays += 1;
        } else {
            s.lowStatDays = 0;
        }

        if (s.succubusVitality < 75) {
            s.lowVitalityDays += 1;
        } else {
            s.lowVitalityDays = 0;
        }

        s.userVitality = clamp(s.userVitality + 40, 0, 100);
        s.lastDrain = 0;
        s.caredToday = false;
    }
    syncVitalityAndNeed(s);
}

function applySetName(s, rawName) {
    const cleaned = String(rawName || '').trim().replace(/^["']|["']$/g, '').slice(0, 48);
    if (!cleaned) {
        return { ok: false, error: 'Please provide a name (e.g. !succubus name: Mira).' };
    }
    const firstNaming = s.name === 'Unknown';
    s.name = cleaned;
    s.bond = clamp(s.bond + (firstNaming ? 4 : 2), 0, 100);
    s.trust = clamp(s.trust + (firstNaming ? 3 : 1), 0, 100);
    s.caredToday = true;
    s.neglectDays = Math.max(0, s.neglectDays - 1);
    syncVitalityAndNeed(s);
    updateMoodAndNeed(s, 'Anchored', 'Reassurance');
    const prog = evaluateProgression(s);
    return {
        ok: true,
        event: 'Named companion "' + s.name + '".',
        guidance: 'React emotionally to receiving the name ' + s.name + '. Show vulnerability and attachment.',
        prog,
    };
}

function applySetRule(s, rawRule) {
    const cleaned = String(rawRule || '').trim().slice(0, 200);
    if (!cleaned) {
        return { ok: false, error: 'Please specify a rule (e.g. !succubus set-rule: No feeding without permission).' };
    }
    if (!s.rules.includes(cleaned)) {
        s.rules = [...s.rules, cleaned];
    }
    s.discipline = clamp(s.discipline + 4, 0, 100);
    s.trust = clamp(s.trust + 1, 0, 100);
    s.caredToday = true;
    syncVitalityAndNeed(s);
    updateMoodAndNeed(s, s.discipline < 15 ? 'Nervous' : 'Attentive', 'Safe feeding rule');
    const prog = evaluateProgression(s);
    return {
        ok: true,
        event: 'Set household rule: "' + cleaned + '".',
        guidance: 'Acknowledge the rule ("' + cleaned + '"). Reflect current Discipline (' + s.discipline + ') and Hunger/Sustenance Need (' + s.sustenanceNeed + ').',
        prog,
    };
}

function applyProtection(s, rawMode) {
    const mode = normalizeProtection(rawMode);
    if (!mode) {
        return {
            ok: false,
            error: 'Invalid protection mode. Choose one of: none, condom, dental barrier, charm, ward.',
        };
    }
    s.protection = mode;
    if (mode !== 'none') {
        s.trust = clamp(s.trust + 3, 0, 100);
        s.control = clamp(s.control + 1, 0, 100);
        s.discipline = clamp(s.discipline + 1, 0, 100);
        s.caredToday = true;
    }
    syncVitalityAndNeed(s);
    updateMoodAndNeed(s, mode === 'none' ? 'Exposed' : 'Focused', mode === 'none' ? 'Careful boundaries' : 'Controlled feeding');
    const prog = evaluateProgression(s);
    return {
        ok: true,
        event: 'Protection mode set to "' + mode + '".',
        guidance: 'Protection is now "' + mode + '". Reflect the physical or magical barrier in the scene.',
        prog,
    };
}

function getProtectionMultiplier(protection, contactType) {
    if (protection === 'ward') return 0.15;
    if (protection === 'charm') return 0.4;
    if (protection === 'condom') {
        return (contactType === 'vaginal' || contactType === 'anal' || contactType === 'tail' || contactType === 'prolonged')
            ? 0.2
            : 1.0;
    }
    if (protection === 'dental barrier') {
        return (contactType === 'kiss' || contactType === 'oral') ? 0.25 : 1.0;
    }
    return 1.0;
}

function getRouteDrainMultiplier(s) {
    if (s.route === 'Starved Horror') return 1.5;
    if (s.route === 'Huntress Succubus' || s.route === 'Assertive Demoness') return 1.25;
    if (s.route === 'Chaotic Temptress') return 1.2;
    if (s.route === 'Gentle Companion' || s.route === 'Balanced Succubus') return 0.85;
    return 1.0;
}

function applyContact(s, rawType, rawIntensity) {
    let contactType = normalizeContactType(rawType);
    let intensity = rawIntensity;

    // Support inline intensity like "kiss 4" or "prolonged 8"
    if (!contactType && typeof rawType === 'string') {
        const parts = rawType.trim().split(/\s+/);
        if (parts.length >= 2) {
            const maybeNum = Number(parts[parts.length - 1]);
            if (Number.isFinite(maybeNum)) {
                const candidateType = normalizeContactType(parts.slice(0, -1).join(' '));
                if (candidateType) {
                    contactType = candidateType;
                    if (intensity === undefined || intensity === null) {
                        intensity = maybeNum;
                    }
                }
            }
        }
    }

    if (!contactType) {
        return {
            ok: false,
            error: 'Invalid contact type. Use: kiss, oral, vaginal, anal, tail, or prolonged.',
        };
    }

    const base = CONTACT_BASE_DRAIN[contactType] || 3;
    const parsedIntensity = Number(intensity);
    const hasIntensity = Number.isFinite(parsedIntensity) && parsedIntensity > 0;
    const clampedIntensity = hasIntensity ? clamp(parsedIntensity, 1, 10) : 5;
    // Scale mildly around baseline intensity 5 -> 0.72x at 1, 1.0x at 5, 1.35x at 10
    const intensityMult = hasIntensity ? (0.65 + clampedIntensity * 0.07) : 1.0;

    const hungerMult = s.sustenanceNeed >= 70
        ? 1.35
        : (s.sustenanceNeed >= 50 ? 1.1 : 1.0);
    const routeMult = getRouteDrainMultiplier(s);
    const protMult = getProtectionMultiplier(s.protection, contactType);

    let drain = Math.round(base * intensityMult * hungerMult * routeMult * protMult);
    if (s.protection === 'none') {
        drain = Math.max(1, drain);
    } else if (s.protection === 'ward' && contactType === 'kiss' && clampedIntensity <= 4 && s.sustenanceNeed < 70) {
        drain = Math.max(0, drain);
    }

    drain = clamp(drain, 0, s.userVitality);
    s.userVitality = clamp(s.userVitality - drain, 0, 100);
    s.lastDrain = drain;

    const vitalityGain = Math.max(drain > 0 ? drain * 4 : 3, 0);
    s.succubusVitality = clamp(s.succubusVitality + vitalityGain, 0, 100);
    s.bond = clamp(s.bond + (drain > 0 ? 2 : 1), 0, 100);
    s.trust = clamp(s.trust + (s.protection !== 'none' ? 2 : 1), 0, 100);
    s.tempt = clamp(s.tempt + (contactType === 'kiss' ? 1 : 3), 0, 100);
    s.caredToday = true;
    s.neglectDays = Math.max(0, s.neglectDays - 1);
    syncVitalityAndNeed(s);

    const dangerWarning = s.userVitality <= 25
        ? 'CRITICAL: {{user}} Vitality is dangerously low (' + s.userVitality + '/100)!'
        : (drain >= 12 ? 'Heavy vitality drain occurred (' + drain + ').' : '');

    if (s.stage === 'Awakened' && drain > 0 && s.protection === 'none') {
        updateMoodAndNeed(s, 'Alarmed', 'Pace contact');
    } else if (s.userVitality <= 35) {
        updateMoodAndNeed(s, 'Guilty-anxious', 'Stop & stabilize {{user}}');
    } else {
        updateMoodAndNeed(s, null, null);
    }

    const prog = evaluateProgression(s);
    return {
        ok: true,
        drain,
        contactType,
        intensity: clampedIntensity,
        event: 'Mucosal contact (' + contactType + ', protection: ' + s.protection + ') drained ' + drain + ' {{user}} Vitality -> Succubus Vitality ' + s.succubusVitality + '/100.',
        guidance: 'Describe the sensory warmth and physical weakness from mucosal vitality drain (' + drain + ' drained; {{user}} Vitality ' + s.userVitality + '/100; never blood/biting). ' + dangerWarning + ' Never dictate {{user}} feelings or choices.',
        prog,
    };
}

function applyFeed(s, rawSource, rawIntensity) {
    const source = normalizeFeedSource(rawSource);
    if (!source) {
        return {
            ok: false,
            error: 'Invalid feed source. Use: affection, praise, dream, magic, admiration, vitality, or food.',
        };
    }

    const mult = Number.isFinite(Number(rawIntensity)) && Number(rawIntensity) > 0
        ? clamp(rawIntensity, 1, 10) / 5
        : 1.0;

    let vitalGain = 15;
    let userDrain = 0;

    switch (source) {
        case 'affection':
            vitalGain = Math.round(18 * mult);
            s.bond = clamp(s.bond + 3, 0, 100);
            s.trust = clamp(s.trust + 3, 0, 100);
            s.empathy = clamp(s.empathy + 2, 0, 100);
            updateMoodAndNeed(s, 'Warm', 'Closeness');
            break;
        case 'praise':
            vitalGain = Math.round(20 * mult);
            s.bond = clamp(s.bond + 2, 0, 100);
            s.sub = clamp(s.sub + 2, 0, 100);
            s.confidence = clamp(s.confidence + 2, 0, 100);
            s.domesticity = clamp(s.domesticity + 2, 0, 100);
            updateMoodAndNeed(s, 'Eager', 'Safe reward');
            break;
        case 'dream':
            vitalGain = Math.round(24 * mult);
            s.tempt = clamp(s.tempt + 2, 0, 100);
            s.control = clamp(s.control + 2, 0, 100);
            updateMoodAndNeed(s, 'Dreamy', 'Dream boundaries');
            break;
        case 'magic':
            vitalGain = Math.round(25 * mult);
            s.control = clamp(s.control + 3, 0, 100);
            s.discipline = clamp(s.discipline + 2, 0, 100);
            updateMoodAndNeed(s, 'Steadied', 'Mana discipline');
            break;
        case 'admiration':
            vitalGain = Math.round(18 * mult);
            s.pride = clamp(s.pride + 3, 0, 100);
            s.confidence = clamp(s.confidence + 3, 0, 100);
            s.tempt = clamp(s.tempt + 2, 0, 100);
            updateMoodAndNeed(s, 'Flattered', 'Balanced pride');
            break;
        case 'vitality': {
            vitalGain = Math.round(50 * mult);
            const protMult = s.protection === 'ward' ? 0.5 : (s.protection === 'charm' ? 0.7 : 1.0);
            userDrain = clamp(Math.round(10 * mult * protMult), 1, s.userVitality);
            s.userVitality = clamp(s.userVitality - userDrain, 0, 100);
            s.lastDrain = userDrain;
            s.bond = clamp(s.bond + 4, 0, 100);
            s.trust = clamp(s.trust + 4, 0, 100);
            s.empathy = clamp(s.empathy + 2, 0, 100);
            updateMoodAndNeed(s, 'Sustained', 'Guidance');
            break;
        }
        case 'food':
            vitalGain = Math.round(6 * mult);
            s.trust = clamp(s.trust + 1, 0, 100);
            updateMoodAndNeed(s, 'Comforted-hungry', 'True vital sustenance');
            break;
    }

    s.succubusVitality = clamp(s.succubusVitality + vitalGain, 0, 100);
    s.caredToday = true;
    s.neglectDays = Math.max(0, s.neglectDays - 1);
    syncVitalityAndNeed(s);
    const prog = evaluateProgression(s);

    const extraFoodNote = source === 'food'
        ? 'Normal food barely eases succubus Sustenance Need (+' + vitalGain + ' Vitality); remind her softly that vital energy is her real sustenance.'
        : 'Sustenance from ' + source + ' raised Succubus Vitality to ' + s.succubusVitality + '/100 (Sustenance Need ' + s.sustenanceNeed + ').';

    return {
        ok: true,
        source,
        vitalGain,
        userDrain,
        event: 'Fed via ' + source + ' (+' + vitalGain + ' Succubus Vitality' + (userDrain ? ', ' + userDrain + ' {{user}} Vitality drained' : '') + ').',
        guidance: extraFoodNote + ' Never describe blood drinking.',
        prog,
    };
}

function applyTrain(s, rawStat, rawIntensity) {
    const stat = normalizeTrainStat(rawStat);
    if (!stat) {
        return {
            ok: false,
            error: 'Invalid training stat. Use: discipline, control, domesticity, predation, confidence, empathy, pride, restraint, dominance, or submission.',
        };
    }

    const step = Number.isFinite(Number(rawIntensity)) && Number(rawIntensity) > 0
        ? clamp(Math.round(Number(rawIntensity) * 2), 3, 18)
        : 8;

    switch (stat) {
        case 'discipline':
            s.discipline = clamp(s.discipline + step, 0, 100);
            s.control = clamp(s.control + Math.ceil(step / 3), 0, 100);
            break;
        case 'control':
            s.control = clamp(s.control + step, 0, 100);
            s.discipline = clamp(s.discipline + Math.ceil(step / 3), 0, 100);
            break;
        case 'restraint':
            s.discipline = clamp(s.discipline + Math.ceil(step * 0.7), 0, 100);
            s.control = clamp(s.control + Math.ceil(step * 0.7), 0, 100);
            s.tempt = clamp(s.tempt - 2, 0, 100);
            break;
        case 'domesticity':
            s.domesticity = clamp(s.domesticity + step + 2, 0, 100);
            s.bond = clamp(s.bond + Math.ceil(step / 2), 0, 100);
            s.trust = clamp(s.trust + Math.ceil(step / 3), 0, 100);
            s.discipline = clamp(s.discipline + Math.ceil(step / 3), 0, 100);
            break;
        case 'predation':
            s.predation = clamp(s.predation + step + 2, 0, 100);
            s.confidence = clamp(s.confidence + Math.ceil(step / 3), 0, 100);
            s.discipline = clamp(s.discipline + Math.ceil(step / 4), 0, 100);
            break;
        case 'confidence':
            s.confidence = clamp(s.confidence + step, 0, 100);
            s.pride = clamp(s.pride + Math.ceil(step / 3), 0, 100);
            break;
        case 'empathy':
            s.empathy = clamp(s.empathy + step + 2, 0, 100);
            s.trust = clamp(s.trust + Math.ceil(step / 2), 0, 100);
            s.bond = clamp(s.bond + Math.ceil(step / 3), 0, 100);
            break;
        case 'pride':
            s.pride = clamp(s.pride + step + 2, 0, 100);
            s.confidence = clamp(s.confidence + Math.ceil(step / 2), 0, 100);
            break;
        case 'dominance':
            s.dom = clamp(s.dom + step, 0, 100);
            s.pride = clamp(s.pride + Math.ceil(step / 2), 0, 100);
            s.confidence = clamp(s.confidence + Math.ceil(step / 2), 0, 100);
            break;
        case 'submission':
            s.sub = clamp(s.sub + step, 0, 100);
            s.trust = clamp(s.trust + Math.ceil(step / 2), 0, 100);
            s.discipline = clamp(s.discipline + Math.ceil(step / 3), 0, 100);
            break;
    }

    s.caredToday = true;
    s.neglectDays = Math.max(0, s.neglectDays - 1);
    syncVitalityAndNeed(s);
    updateMoodAndNeed(s, null, null);
    const prog = evaluateProgression(s);
    return {
        ok: true,
        stat,
        event: 'Trained ' + stat + ' (+' + step + '). Current Stage: ' + s.stage + ', Route: ' + formatDisplayedRoute(s) + '.',
        guidance: 'Show active practice/training in ' + stat + ' and how it shapes her posture, aura, and habits.',
        prog,
    };
}

function applyComfort(s, rawIntensity) {
    const step = Number.isFinite(Number(rawIntensity)) && Number(rawIntensity) > 0
        ? clamp(rawIntensity, 1, 10)
        : 5;
    const trustGain = Math.max(3, Math.round(step * 1.2));
    const bondGain = Math.max(3, Math.round(step * 1.0));
    const empGain = Math.max(2, Math.round(step * 0.6));
    const vitGain = Math.max(8, Math.round(step * 2.5));

    s.trust = clamp(s.trust + trustGain, 0, 100);
    s.bond = clamp(s.bond + bondGain, 0, 100);
    s.empathy = clamp(s.empathy + empGain, 0, 100);
    s.succubusVitality = clamp(s.succubusVitality + vitGain, 0, 100);
    s.caredToday = true;
    s.neglectDays = Math.max(0, s.neglectDays - 1);
    syncVitalityAndNeed(s);
    updateMoodAndNeed(s, s.stage === 'Awakened' ? 'Softened' : null, 'Reassurance');
    const prog = evaluateProgression(s);
    return {
        ok: true,
        event: 'Comforted companion (+' + bondGain + ' Bond, +' + trustGain + ' Trust, +' + vitGain + ' Succubus Vitality).',
        guidance: 'Her aura warms and steadies in response to shelter and reassurance.',
        prog,
    };
}

function applyRecoverUserVitality(s, rawMethod, rawAmount) {
    let methodToken = rawMethod;
    let explicitAmount = rawAmount;

    if (typeof rawMethod === 'string' && rawMethod.trim()) {
        const trimmed = rawMethod.trim();
        if (/^\d+$/.test(trimmed) && (explicitAmount === undefined || explicitAmount === null)) {
            explicitAmount = Number(trimmed);
            methodToken = 'rest';
        } else {
            const parts = trimmed.split(/\s+/);
            if (parts.length >= 2 && /^\d+$/.test(parts[parts.length - 1]) && (explicitAmount === undefined || explicitAmount === null)) {
                explicitAmount = Number(parts[parts.length - 1]);
                methodToken = parts.slice(0, -1).join(' ');
            }
        }
    }

    const method = normalizeRecoveryMethod(methodToken);
    if (!method) {
        return {
            ok: false,
            error: 'Invalid recovery method. Use: rest, meal, sleep, healing, full, or a number (1-100).',
        };
    }

    const parsedAmount = Number(explicitAmount);
    const hasExplicitAmount = explicitAmount !== undefined && explicitAmount !== null && explicitAmount !== '' && Number.isFinite(parsedAmount);
    const requestedGain = hasExplicitAmount ? clamp(parsedAmount, 1, 100) : (USER_RECOVERY_AMOUNTS[method] || 15);

    const prev = s.userVitality;
    s.userVitality = clamp(s.userVitality + requestedGain, 0, 100);
    const gained = s.userVitality - prev;
    if (s.userVitality >= 100 || method === 'sleep' || method === 'full') {
        s.lastDrain = 0;
    }
    syncVitalityAndNeed(s);
    updateMoodAndNeed(s, null, null);
    const prog = evaluateProgression(s);

    return {
        ok: true,
        method,
        gained,
        requestedGain,
        event: '{{user}} Vitality recovered via ' + method + ' (+' + gained + ' -> ' + s.userVitality + '/100).',
        guidance: 'Reflect {{user}} regaining steadiness and strength (' + s.userVitality + '/100) through ' + method + ' without dictating {{user}} choices.',
        prog,
    };
}

function applyForceEvolve(s) {
    const curIdx = STAGE_ORDER[s.stage] ?? 0;
    if (curIdx >= STAGE_ORDER.Ascendant) {
        const portraitUrl = getImageForState(s.stage, s.route);
        return {
            ok: true,
            alreadyMax: true,
            event: s.name + ' is already Ascendant on the ' + s.route + ' route.',
            guidance: 'She is already Ascendant (' + s.route + '). Narrate her integrated mastery.',
            prog: {
                stageChanged: false,
                prevStage: s.stage,
                nextStage: s.stage,
                portraitUrl,
                appendMarkdown: '',
            },
        };
    }

    const nextIdx = curIdx + 1;
    const nextStage = STAGES[nextIdx];
    if (nextStage === 'Imprinted' && s.succubusVitality < 100) {
        s.succubusVitality = 100;
    } else if (nextStage === 'Shaped' && getHighestEvolutionStat(s) < 50 && !isHorrorCondition(s)) {
        s.bond = Math.max(s.bond, 50);
    } else if (nextStage === 'Defined' && getHighestEvolutionStat(s) < 75 && s.neglectDays < 7) {
        s.bond = Math.max(s.bond, 75);
    } else if (nextStage === 'Ascendant' && getHighestEvolutionStat(s) < 100) {
        s.bond = Math.max(s.bond, 100);
    }
    syncVitalityAndNeed(s);
    updateMoodAndNeed(s, null, null);
    const prog = evaluateProgression(s);
    return {
        ok: true,
        event: 'Evolution milestone triggered: ' + prog.prevStage + ' -> ' + prog.nextStage + ' (' + formatDisplayedRoute(s) + ').',
        guidance: 'Narrate the visible stage evolution (' + prog.prevStage + ' -> ' + prog.nextStage + ') in horns, wings, tail, aura, and voice without speaking system terms aloud.',
        prog,
    };
}

function buildActionPromptInjection(s, summary, prog) {
    const displayedRoute = formatDisplayedRoute(s);
    const guide = ROUTE_GUIDANCE[s.route] || ROUTE_GUIDANCE.Undefined;
    const lines = [
        '[SCRIPT_EVENT] Pre-turn succubus command handled: ' + summary,
        'Authoritative State: Name=' + s.name + ', Stage=' + s.stage + ', Route=' + displayedRoute + (s.routeLocked ? ' (LOCKED)' : ' (mutable lean)') + ', Succubus Vitality=' + s.succubusVitality + '/100, Sustenance Need=' + s.sustenanceNeed + '/100, User Vitality=' + s.userVitality + '/100, Last Drain=' + s.lastDrain + ', Protection=' + s.protection + '.',
        'Voice/Presence Guidance: ' + guide.voice + '. Appearance: ' + guide.appearance + '.',
        'Do NOT re-call Script_SuccubusCompanion for this already-handled command. Never decide {{user}} thoughts, consent, or choices.',
    ];
    if (prog && prog.stageChanged) {
        lines.push('STAGE TRANSITION (' + prog.prevStage + ' -> ' + prog.nextStage + '): Narrate the visible shift in horns, wings, tail, aura, posture, and voice naturally.');
    }
    return lines.join('\n');
}

function onBeforeGenerate(state, ctx) {
    let s = ensureStateShape(state);
    const events = [];

    const deltaMinutes = Math.max(0, Number(ctx?.time?.deltaMinutes || 0));
    const dayChanged = Boolean(ctx?.time?.dayChanged);

    if (deltaMinutes > 0) {
        const decay = Math.floor(deltaMinutes / 15);
        if (decay > 0) {
            s.succubusVitality = clamp(s.succubusVitality - decay, 0, 100);
            syncVitalityAndNeed(s);
            events.push('Elapsed ' + deltaMinutes + 'm: Succubus Vitality -' + decay + ' (Need ' + s.sustenanceNeed + ').');
        }
        const userRegen = Math.floor(deltaMinutes / 30);
        if (userRegen > 0 && s.userVitality < 100) {
            const prevUserVit = s.userVitality;
            s.userVitality = clamp(s.userVitality + userRegen, 0, 100);
            const gained = s.userVitality - prevUserVit;
            if (gained > 0) {
                if (s.userVitality >= 100) s.lastDrain = 0;
                events.push('Elapsed ' + deltaMinutes + 'm: {{user}} Vitality +' + gained + ' (' + s.userVitality + '/100).');
            }
        }
    }

    if (dayChanged) {
        const prevDay = s.day;
        applyDayRollover(s, 1, false);
        events.push('Day changed (' + prevDay + ' -> ' + s.day + ', Neglect ' + s.neglectDays + ').');
    }

    const cmd = ctx?.command;
    if (!cmd || !cmd.subcommand) {
        updateMoodAndNeed(s, null, null);
        const prog = evaluateProgression(s);
        const out = {
            state: s,
            portraitUrl: prog.portraitUrl,
        };
        if (prog.appendMarkdown) out.appendMarkdown = prog.appendMarkdown;
        if (prog.stageChanged || s.sustenanceNeed >= 75 || s.userVitality <= 30 || events.length > 0) {
            const notes = [...events];
            if (prog.stageChanged) {
                notes.push('STAGE TRANSITION: ' + prog.prevStage + ' -> ' + prog.nextStage + ' (' + formatDisplayedRoute(s) + '). Narrate the visible physical/aura shift naturally.');
            }
            if (s.sustenanceNeed >= 75) {
                notes.push('HIGH SUSTENANCE NEED (' + s.sustenanceNeed + '/100): Show aura flicker, trembling control, and hunger pressure (never blood craving).');
            }
            if (s.userVitality <= 30) {
                notes.push('LOW USER VITALITY (' + s.userVitality + '/100): Reflect physical weakness/exhaustion consequences without dictating {{user}} choices.');
            }
            out.promptInjection = notes.join('\n');
        }
        return out;
    }

    const sub = String(cmd.subcommand || '').trim().toLowerCase();
    const rawArgs = String(cmd.rawArgs || '').trim();

    if (sub === 'reset') {
        const fresh = initState();
        const prog = evaluateProgression(fresh);
        return {
            state: fresh,
            portraitUrl: BASE_AWAKENED_IMAGE,
            appendMarkdown: '![](' + BASE_AWAKENED_IMAGE + ')',
            immediateReply: 'Succubus Companion state reset to Awakened (Storm Door).',
            promptInjection: buildActionPromptInjection(fresh, 'State reset to Awakened.', prog),
        };
    }

    if (sub === 'status' || sub === 'hud') {
        const prog = evaluateProgression(s);
        return {
            state: s,
            portraitUrl: prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, 'Requested HUD status.\n' + buildCompactHudText(s), prog),
        };
    }

    if (sub === 'route' || sub === 'lean') {
        const prog = evaluateProgression(s);
        const scores = computeRouteScores(s);
        const top3 = Object.entries(scores)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 3)
            .map(([r, sc]) => r + ' (' + Math.round(sc) + ')')
            .join(', ');
        return {
            state: s,
            portraitUrl: prog.portraitUrl,
            promptInjection: buildActionPromptInjection(
                s,
                'Inspected route (' + formatDisplayedRoute(s) + '; locked=' + s.routeLocked + '). Top tendencies: ' + top3 + '.',
                prog
            ),
        };
    }

    if (sub === 'intimacy' || sub === 'preferences') {
        const prog = evaluateProgression(s);
        const pref = computeIntimacyProfile(s);
        return {
            state: s,
            portraitUrl: prog.portraitUrl,
            promptInjection: buildActionPromptInjection(
                s,
                'Intimacy profile: ' + pref.stance + '; ' + pref.safety + '; themes: ' + pref.themes.join(', ') + '.',
                prog
            ),
        };
    }

    if (sub === 'memory') {
        const prog = evaluateProgression(s);
        const rulesText = s.rules.length ? s.rules.join(' | ') : 'None yet';
        return {
            state: s,
            portraitUrl: prog.portraitUrl,
            promptInjection: buildActionPromptInjection(
                s,
                'Memory summary: Name=' + s.name + ', Day=' + s.day + ', Neglect=' + s.neglectDays + ', Rules=[' + rulesText + '].',
                prog
            ),
        };
    }

    if (sub === 'vitality' || sub === 'drain') {
        const prog = evaluateProgression(s);
        const guide = ROUTE_GUIDANCE[s.route] || ROUTE_GUIDANCE.Undefined;
        return {
            state: s,
            portraitUrl: prog.portraitUrl,
            promptInjection: buildActionPromptInjection(
                s,
                'Vitality check: {{user}} ' + s.userVitality + '/100, Last Drain ' + s.lastDrain + ', Protection ' + s.protection + ', Succubus Vitality ' + s.succubusVitality + '/100 (' + guide.drainNote + ').',
                prog
            ),
        };
    }

    if (sub === 'portrait' || sub === 'image') {
        const prog = evaluateProgression(s);
        if (prog.portraitUrl && !s.shownImages.includes(prog.portraitUrl)) {
            s.shownImages = [...s.shownImages, prog.portraitUrl];
        }
        return {
            state: s,
            portraitUrl: prog.portraitUrl,
            appendMarkdown: '![](' + prog.portraitUrl + ')',
            promptInjection: buildActionPromptInjection(s, 'Displayed portrait for ' + s.stage + ' / ' + formatDisplayedRoute(s) + '.', prog),
        };
    }

    if (sub === 'name') {
        const res = applySetName(s, rawArgs);
        if (!res.ok) {
            return { state: s, portraitUrl: getImageForState(s.stage, s.route), promptInjection: '[SCRIPT_EVENT] ' + res.error };
        }
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'set-rule' || sub === 'set_rule') {
        const res = applySetRule(s, rawArgs);
        if (!res.ok) {
            return { state: s, portraitUrl: getImageForState(s.stage, s.route), promptInjection: '[SCRIPT_EVENT] ' + res.error };
        }
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'protection') {
        const res = applyProtection(s, rawArgs);
        if (!res.ok) {
            return { state: s, portraitUrl: getImageForState(s.stage, s.route), promptInjection: '[SCRIPT_EVENT] ' + res.error };
        }
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'contact') {
        const res = applyContact(s, rawArgs, undefined);
        if (!res.ok) {
            return { state: s, portraitUrl: getImageForState(s.stage, s.route), promptInjection: '[SCRIPT_EVENT] ' + res.error };
        }
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'feed') {
        const res = applyFeed(s, rawArgs, undefined);
        if (!res.ok) {
            return { state: s, portraitUrl: getImageForState(s.stage, s.route), promptInjection: '[SCRIPT_EVENT] ' + res.error };
        }
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'train') {
        const res = applyTrain(s, rawArgs, undefined);
        if (!res.ok) {
            return { state: s, portraitUrl: getImageForState(s.stage, s.route), promptInjection: '[SCRIPT_EVENT] ' + res.error };
        }
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'comfort') {
        const res = applyComfort(s, rawArgs ? Number(rawArgs) : undefined);
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'evolve') {
        const res = applyForceEvolve(s);
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'rest' || sub === 'recover' || sub === 'heal' || sub === 'recover-vitality' || sub === 'recover_vitality') {
        const defaultMethod = sub === 'heal' ? 'healing' : 'rest';
        const res = applyRecoverUserVitality(s, rawArgs || defaultMethod);
        if (!res.ok) {
            return { state: s, promptInjection: '[SCRIPT_EVENT] ' + res.error };
        }
        const out = {
            state: s,
            portraitUrl: res.prog.portraitUrl,
            promptInjection: buildActionPromptInjection(s, res.event + ' ' + res.guidance, res.prog),
        };
        if (res.prog.appendMarkdown) out.appendMarkdown = res.prog.appendMarkdown;
        return out;
    }

    if (sub === 'pass-day' || sub === 'pass_day') {
        const countMatch = rawArgs.match(/(\d+)/);
        const count = countMatch ? Number(countMatch[1]) : 1;
        const explicitNeglect = !rawArgs || /neglect/i.test(rawArgs) || (!/care/i.test(rawArgs) && !s.caredToday);
        applyDayRollover(s, count, explicitNeglect);
        updateMoodAndNeed(s, null, null);
        const prog = evaluateProgression(s);
        const out = {
            state: s,
            portraitUrl: prog.portraitUrl,
            promptInjection: buildActionPromptInjection(
                s,
                'Passed ' + clamp(count, 1, 30) + ' day(s) (Day ' + s.day + ', Neglect ' + s.neglectDays + ').',
                prog
            ),
        };
        if (prog.appendMarkdown) out.appendMarkdown = prog.appendMarkdown;
        return out;
    }

    const prog = evaluateProgression(s);
    return {
        state: s,
        portraitUrl: prog.portraitUrl,
        promptInjection: '[SCRIPT_EVENT] Unknown !succubus subcommand "' + sub + '". Valid commands: status, hud, route, lean, intimacy, preferences, memory, vitality, drain, portrait, image, name, set-rule, comfort, feed, train, protection, contact, evolve, rest, recover, heal, pass-day, reset.',
    };
}

function onToolCall(state, call) {
    let s = ensureStateShape(state);
    const actionRaw = typeof call === 'string' ? call : call?.action;
    const args = (call && typeof call === 'object' && call.args && typeof call.args === 'object') ? call.args : {};
    const action = String(actionRaw || '').trim().toLowerCase().replace(/-/g, '_');

    let res = null;
    if (action === 'set_name') {
        res = applySetName(s, args.name);
    } else if (action === 'set_rule') {
        res = applySetRule(s, args.rule);
    } else if (action === 'protection') {
        res = applyProtection(s, args.mode);
    } else if (action === 'contact') {
        res = applyContact(s, args.type, args.intensity);
    } else if (action === 'feed') {
        res = applyFeed(s, args.source, args.intensity);
    } else if (action === 'train') {
        res = applyTrain(s, args.stat, args.intensity);
    } else if (action === 'comfort') {
        res = applyComfort(s, args.intensity);
    } else if (action === 'evolve') {
        res = applyForceEvolve(s);
    } else if (action === 'recover_vitality' || action === 'rest' || action === 'recover' || action === 'heal') {
        res = applyRecoverUserVitality(s, args.method || (action === 'heal' ? 'healing' : 'rest'), args.amount);
    } else if (action === 'pass_day') {
        const forceNeglect = args.neglected !== undefined ? Boolean(args.neglected) : !s.caredToday;
        applyDayRollover(s, 1, forceNeglect);
        updateMoodAndNeed(s, null, null);
        const prog = evaluateProgression(s);
        res = {
            ok: true,
            event: 'Day passed (Day ' + s.day + ', Neglect ' + s.neglectDays + ').',
            guidance: s.neglectDays >= 3
                ? 'Neglect and hunger weigh heavily on her aura; reflect desperation without blood craving.'
                : 'A new day begins; reflect her updated vitality and mood.',
            prog,
        };
    } else if (action === 'status') {
        const prog = evaluateProgression(s);
        const pref = computeIntimacyProfile(s);
        const guide = ROUTE_GUIDANCE[s.route] || ROUTE_GUIDANCE.Undefined;
        return {
            state: s,
            portraitUrl: prog.portraitUrl,
            toolResult: {
                ok: true,
                name: s.name,
                stage: s.stage,
                route: formatDisplayedRoute(s),
                rawRoute: s.route,
                routeLocked: s.routeLocked,
                succubusVitality: s.succubusVitality,
                sustenanceNeed: s.sustenanceNeed,
                userVitality: s.userVitality,
                lastDrain: s.lastDrain,
                protection: s.protection,
                day: s.day,
                neglectDays: s.neglectDays,
                mood: s.mood,
                need: s.need,
                rules: s.rules,
                intimacy: pref,
                voiceGuidance: guide.voice,
                appearanceGuidance: guide.appearance,
                hud: buildCompactHudText(s),
            },
        };
    } else {
        return {
            state: s,
            toolResult: { ok: false, error: 'Unsupported action: ' + String(actionRaw || '') },
        };
    }

    if (!res.ok) {
        return {
            state: s,
            toolResult: { ok: false, error: res.error },
        };
    }

    const guide = ROUTE_GUIDANCE[s.route] || ROUTE_GUIDANCE.Undefined;
    const out = {
        state: s,
        portraitUrl: res.prog.portraitUrl,
        toolResult: {
            ok: true,
            action,
            event: res.event,
            guidance: res.guidance,
            stageChanged: res.prog.stageChanged,
            prevStage: res.prog.prevStage,
            stage: s.stage,
            route: formatDisplayedRoute(s),
            rawRoute: s.route,
            routeLocked: s.routeLocked,
            succubusVitality: s.succubusVitality,
            sustenanceNeed: s.sustenanceNeed,
            userVitality: s.userVitality,
            lastDrain: s.lastDrain,
            protection: s.protection,
            day: s.day,
            neglectDays: s.neglectDays,
            mood: s.mood,
            need: s.need,
            portraitUrl: res.prog.portraitUrl,
            voiceGuidance: guide.voice,
            appearanceGuidance: guide.appearance,
            hud: buildCompactHudText(s),
        },
    };
    if (res.prog.appendMarkdown) {
        out.appendMarkdown = res.prog.appendMarkdown;
    }
    return out;
}

function onAfterGenerate(state) {
    const s = ensureStateShape(state);
    const prog = evaluateProgression(s);
    return {
        state: s,
        portraitUrl: prog.portraitUrl,
    };
}

function renderMemo(state) {
    const s = ensureStateShape(state);
    const displayedRoute = formatDisplayedRoute(s);
    const routeTag = s.routeLocked ? displayedRoute + ' (Locked)' : displayedRoute;
    const needColor = s.sustenanceNeed >= 75 ? 'RED' : (s.sustenanceNeed >= 50 ? 'ORANGE' : 'PINK');
    const userVitColor = s.userVitality <= 30 ? 'RED' : (s.userVitality <= 60 ? 'ORANGE' : 'GREEN');
    const pills = [s.stage, routeTag, 'Mood: ' + s.mood];
    if (s.protection !== 'none') {
        pills.push('Ward/Prot: ' + s.protection);
    }

    const lines = [
        'Identity: ' + s.name + ' · Day ' + s.day + ' · Neglect ' + s.neglectDays,
        'Stage & Route: ((PILLS)) ' + pills.join(', '),
        'Succubus Vitality: ((BAR - #e879f9 #ec4899)) ' + s.succubusVitality + '/100',
        'Sustenance Need: ((BAR' + needColor + ')) ' + s.sustenanceNeed + '/100',
        '{{user}} Vitality: ((BAR' + userVitColor + ')) ' + s.userVitality + '/100 (Last Drain ' + s.lastDrain + ')',
        'Bond: ((BAR)) ' + s.bond + '/100 || Trust: ((BAR)) ' + s.trust + '/100',
        'Discipline: ((BAR)) ' + s.discipline + '/100 || Control: ((BAR)) ' + s.control + '/100',
        'Dom / Sub / Tempt: ' + s.dom + ' / ' + s.sub + ' / ' + s.tempt + ' · Pride ' + s.pride + ' · Empathy ' + s.empathy,
        'Domesticity / Predation / Confidence: ' + s.domesticity + ' / ' + s.predation + ' / ' + s.confidence,
        'Current Need: ((PILLS)) ' + s.need + (s.protection === 'none' ? ', Protection: none' : ''),
    ];
    if (s.rules.length > 0) {
        lines.push('Rules: ' + s.rules.join(' | '));
    }
    return lines.join('\n');
}
